"use client";

import { useState } from "react";
import { ChevronLeft, ChevronRight, Plus, X } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createNewTask } from "@/app/actions/task-actions";
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [loading, setLoading] = useState(false);
  
  // Form States
  const [title, setTitle] = useState("");
  const [type, setType] = useState("agenda");

  // DB'den gelen verileri takvimde göstermek için map'liyoruz
  const taskMap = initialTasks.reduce((acc: any, task) => {
    try {
      // description içindeki JSON'ı parse ediyoruz
      const details = JSON.parse(task.description || "{}");
      const dateKey = details.datum; // "yyyy-MM-dd" formatında bekliyoruz
      if (dateKey) {
        if (!acc[dateKey]) acc[dateKey] = [];
        acc[dateKey].push({ ...task, details });
      }
    } catch (e) {
      console.error("Task parse hatası:", task.id);
    }
    return acc;
  }, {});

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    // SERVER ACTION'A GÖNDERİLEN VERİ PAKETİ
    // Not: Bu yapı 'task-actions.ts' içindeki beklentiyle birebir aynı olmalı
    const payload = {
      titel: title,
      sprint: "0", // Agenda/Assignment için varsayılan sprint 0
      documentType: type,
      datum: format(selectedDate, "yyyy-MM-dd"),
    };

    try {
      const res = await createNewTask(payload);
      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        router.refresh(); // Sayfayı yenileyerek yeni veriyi DB'den çeker
      } else {
        alert("Fout bij het opslaan: " + res.error);
      }
    } catch (err) {
      console.error("DB Connection Error:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-10 relative">
      
      {/* HEADER */}
      <div className="flex justify-between items-center mb-12 border-b border-white/5 pb-10">
        <div>
          <h1 className="text-6xl font-black text-white italic tracking-tighter uppercase leading-none shadow-fuchsia-500/20 drop-shadow-2xl">
            Temporal Grid
          </h1>
          <p className="text-fuchsia-500 text-[10px] font-bold tracking-[0.7em] uppercase mt-3 animate-pulse">
            Systeem Status: Actief
          </p>
        </div>
        
        <div className="flex items-center gap-6 bg-[#0a0e17]/80 border border-white/10 p-3 rounded-2xl backdrop-blur-xl shadow-2xl">
          <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all rounded-xl hover:bg-white/5">
            <ChevronLeft size={28} />
          </button>
          <span className="text-xl font-black text-white w-56 text-center uppercase tracking-[0.2em] italic">
            {format(currentMonth, "MMMM yyyy", { locale: nl })}
          </span>
          <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all rounded-xl hover:bg-white/5">
            <ChevronRight size={28} />
          </button>
        </div>
      </div>

      {/* TAKVİM IZGARASI */}
      <div className="bg-[#0a0e17]/90 border border-white/10 rounded-[40px] overflow-hidden shadow-[0_0_100px_rgba(0,0,0,0.5)] backdrop-blur-3xl">
        <div className="grid grid-cols-7 bg-white/5 py-6 border-b border-white/10 text-center">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => (
            <span key={d} className="text-xs font-black text-teal-500/40 uppercase tracking-[0.5em]">{d}</span>
          ))}
        </div>

        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

            while (day <= endDate) {
              const dateKey = format(day, "yyyy-MM-dd");
              const dayTasks = taskMap[dateKey] || [];
              const isCurrentMonth = isSameMonth(day, currentMonth);
              const isToday = isSameDay(day, new Date());
              const currentDay = day;

              days.push(
                <div 
                  key={day.toString()} 
                  onClick={() => setSelectedDate(currentDay)}
                  className={`min-h-[170px] border border-white/5 p-5 transition-all cursor-pointer hover:bg-fuchsia-500/[0.03] relative group ${!isCurrentMonth ? "opacity-5 pointer-events-none" : "opacity-100"}`}
                >
                  <span className={`text-sm font-mono mb-3 block ${isToday ? "text-fuchsia-500 font-black scale-125 origin-left" : "text-teal-500/20"}`}>
                    {format(day, "d")}
                  </span>

                  <div className="space-y-2">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} className={`text-[10px] px-3 py-2 truncate rounded-xl border font-bold uppercase tracking-tighter shadow-lg transition-transform hover:scale-105 ${
                        t.details.documentType === 'agenda' || t.details.documentType === 'assignment' 
                        ? 'bg-blue-600/10 border-blue-500/30 text-blue-400' 
                        : 'bg-fuchsia-600/10 border-fuchsia-500/30 text-fuchsia-400'
                      }`}>
                        {t.title}
                      </div>
                    ))}
                  </div>
                  
                  <div className="absolute bottom-5 right-5 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                    <div className="bg-fuchsia-600 p-1 rounded-lg shadow-[0_0_15px_rgba(217,70,239,0.5)]">
                      <Plus size={16} className="text-white" />
                    </div>
                  </div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {/* HOLLANDACA QUICK ADD PANEL */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#02040a]/95 backdrop-blur-xl animate-in fade-in zoom-in duration-300 px-4">
          <div className="bg-[#0E153A] border border-fuchsia-500/40 p-12 rounded-[40px] w-full max-w-lg shadow-[0_0_100px_rgba(217,70,239,0.2)] relative">
            
            <button onClick={() => setSelectedDate(null)} className="absolute top-8 right-8 text-white/20 hover:text-white transition-colors cursor-pointer p-2 hover:bg-white/5 rounded-full"><X size={32} /></button>
            
            <div className="mb-12">
              <h3 className="text-fuchsia-500 font-black uppercase text-[11px] tracking-[0.6em] mb-4 ml-1">Toevoegen Aan Tijdlijn</h3>
              <p className="text-4xl font-black text-white italic tracking-tighter uppercase leading-none border-l-4 border-fuchsia-600 pl-6">
                {format(selectedDate, "dd MMMM yyyy", { locale: nl })}
              </p>
            </div>

            <div className="space-y-10">
              <div className="space-y-3">
                <label className="text-[11px] font-black uppercase text-teal-500/40 block tracking-widest ml-2">Titel van de vermelding</label>
                <input 
                  autoFocus
                  value={title} onChange={(e) => setTitle(e.target.value)}
                  className="w-full bg-[#070B24] border border-white/10 p-6 text-white font-bold focus:border-fuchsia-500 outline-none transition-all rounded-2xl placeholder:text-white/5 text-lg shadow-inner"
                  placeholder="Bijv. Deadline Opdracht 1..."
                />
              </div>

              <div className="space-y-4">
                <label className="text-[11px] font-black uppercase text-teal-500/40 block tracking-widest ml-2">Selecteer Categorie</label>
                <div className="grid grid-cols-2 gap-4">
                  {[
                    { id: 'agenda', label: '📅 Agenda' },
                    { id: 'assignment', label: '📝 Opdracht' },
                    { id: 'meeting', label: '🤝 Vergadering' },
                    { id: 'daily', label: '⚙️ Daily Scrum' }
                  ].map((cat) => (
                    <button 
                      key={cat.id}
                      onClick={() => setType(cat.id)}
                      className={`py-5 text-[11px] font-black uppercase border transition-all rounded-2xl tracking-widest ${
                        type === cat.id 
                          ? 'bg-fuchsia-600 border-fuchsia-600 text-white shadow-[0_0_30px_rgba(217,70,239,0.5)] scale-105 z-10' 
                          : 'bg-[#070B24] border-white/5 text-white/30 hover:border-white/20'
                      }`}
                    >
                      {cat.label}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={handleSave}
                disabled={loading || !title}
                className="w-full bg-white text-[#0E153A] font-black py-7 mt-6 hover:bg-fuchsia-500 hover:text-white transition-all uppercase text-sm tracking-[0.5em] rounded-[24px] shadow-2xl active:scale-95 disabled:opacity-10"
              >
                {loading ? "Verwerken..." : "Bevestigen"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}